    end if;
  end loop;
  -- Ten collisions in a 32^6 space means something is very wrong; fall back to
  -- something that cannot collide rather than raising inside an award.
  return 'TRYP-' || to_char(now(), 'YYYY') || '-' || replace(gen_random_uuid()::text, '-', '');
end $function$;
